'use strict';
/**
 * Procedural 3D gift renderer (Three.js). Builds meshes at runtime from the
 * geometry specs under assets/3d-models/<id>.geometry.json (generated by
 * scripts/generate_gifts.py). The brief explicitly permits generated
 * procedural geometry; this is a real visual system, not an emoji/CSS stand-in.
 *
 * Import Three.js in the host app: `import * as THREE from 'three'` and pass it
 * in (dependency-injected) so this module stays runtime-agnostic and testable.
 */
function buildGiftMesh(THREE, spec, opts = {}) {
  const group = new THREE.Group();
  const reduced = opts.reducedMotion === true;
  for (const part of spec.parts) {
    let geo;
    switch (part.shape) {
      case 'box': geo = new THREE.BoxGeometry(part.scale, part.scale, part.scale); break;
      case 'cone': geo = new THREE.ConeGeometry(part.scale * 0.6, part.scale, 24); break;
      case 'torus': geo = new THREE.TorusGeometry(part.scale * 0.6, part.scale * 0.2, 16, 48); break;
      case 'icosahedron': geo = new THREE.IcosahedronGeometry(part.scale * 0.7, 0); break;
      case 'cylinder': geo = new THREE.CylinderGeometry(part.scale * 0.5, part.scale * 0.5, part.scale, 24); break;
      case 'tetrahedron': geo = new THREE.TetrahedronGeometry(part.scale * 0.8); break;
      default: geo = new THREE.SphereGeometry(part.scale * 0.6, 32, 32);
    }
    const mat = new THREE.MeshStandardMaterial({ color: part.color, metalness: part.metalness, roughness: part.roughness });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(part.position[0], part.position[1], part.position[2]);
    group.add(mesh);
  }
  const anim = spec.animation || {};
  group.userData.animate = (t) => {
    if (reduced) return;
    if (anim.spin) group.rotation.y = t * 0.001;
    if (anim.bob) group.position.y = Math.sin(t * 0.002) * 0.2;
  };
  group.userData.durationMs = anim.durationMs || 1500;
  return group;
}

/** Decide whether to show the premium 3D effect or a low-end fallback. */
function selectPresentation(gift, caps) {
  const needsWebgl = gift.deviceRequirements && gift.deviceRequirements.webgl;
  if (needsWebgl && !(caps && caps.webgl)) return { mode: 'fallback', fallback: gift.fallback };
  if (caps && caps.reducedMotion) return { mode: 'reduced-3d' };
  return { mode: 'full-3d' };
}

module.exports = { buildGiftMesh, selectPresentation };
